import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"সময় প্রত্যাবর্তনের মূল নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/82-时间回溯基本原则.md","filePath":"bn/82-时间回溯基本原则.md","lastUpdated":null}'),o={name:"bn/82-时间回溯基本原则.md"};function l(i,t,h,n,u,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="সময়-প্রত্যাবর্তনের-মূল-নীতি" tabindex="-1">সময় প্রত্যাবর্তনের মূল নীতি <a class="header-anchor" href="#সময়-প্রত্যাবর্তনের-মূল-নীতি" aria-label="Permalink to &quot;সময় প্রত্যাবর্তনের মূল নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>82</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সময় প্রত্যাবর্তন, আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ, টাইমলাইন স্থিতিশীলতা, কার্য-কারণ সংরক্ষণ, অ্যাঙ্কর অ্যাঙ্করিং</td></tr></tbody></table><h2 id="_1-সময়-প্রত্যাবর্তনের-সংজ্ঞা-ও-সত্তা" tabindex="-1">1. সময় প্রত্যাবর্তনের সংজ্ঞা ও সত্তা <a class="header-anchor" href="#_1-সময়-প্রত্যাবর্তনের-সংজ্ঞা-ও-সত্তা" aria-label="Permalink to &quot;1. সময় প্রত্যাবর্তনের সংজ্ঞা ও সত্তা&quot;">​</a></h2><p>সময় প্রত্যাবর্তন বলতে অ্যাঙ্কর আইন নেটওয়ার্কের সময় মাত্রার অপারেশন ক্ষমতার মাধ্যমে চেতনা, তথ্য বা পদার্থকে অতীতের সময়ের নোডে ফেরানোর আচরণকে বোঝায়। হেংইয়ান-ঝৌর আইন কাঠামোর অধীনে, সময় একমুখী অপরিবর্তনীয় রৈখিক প্রবাহ নয়, বরং আইন নেটওয়ার্কের একটি অপারেটেবল মাত্রা। তবে, সময় মাত্রার অপারেশনে অত্যন্ত উচ্চ ঝুঁকি ও কঠোর সীমাবদ্ধতা রয়েছে, কোনো সময় প্রত্যাবর্তন আচরণই কার্য-কারণ শৃঙ্খলার ব্যাঘাত, টাইমলাইন বিভাজন এমনকি মহাজাগতিক স্তরের আইন কম্পন সৃষ্টি করতে পারে।</p><p>সময় প্রত্যাবর্তনের সত্তা হলো &quot;আইন নেটওয়ার্কের সময় মাত্রায় একটি প্রত্যাবর্তন চ্যানেল তৈরি করা, নির্দিষ্ট তথ্য বা শক্তিকে চ্যানেল বরাবর বিপরীতমুখী প্রচার করা&quot;। এই প্রক্রিয়াতে প্রচুর পরিমাণে অ্যাঙ্কর শক্তি খরচ হয়, এবং প্রত্যাবর্তনের সময় যত পুরোনো, প্রত্যাবর্তনের বিষয়বস্তু যত জটিল, শক্তির খরচ সূচকীয়ভাবে বৃদ্ধি পায়। বর্তমানে হেংইয়ান-ঝৌর প্রযুক্তিগত ক্ষমতা শুধুমাত্র চেতনা ও তথ্য স্তরের প্রত্যাবর্তনকে সমর্থন করে, পদার্থ স্তরের সম্পূর্ণ প্রত্যাবর্তন এখনও তাত্ত্বিক গবেষণার পর্যায়ে রয়েছে।</p><p>বিশেষভাবে জোর দেওয়া প্রয়োজন যে, সময় প্রত্যাবর্তন &quot;টাইম ট্রাভেল&quot; এর সমান নয়। প্রত্যাবর্তনকারী সম্পূর্ণ পদার্থ রূপে অতীতে প্রবেশ করে না, বরং চেতনা প্রজেকশন বা তথ্য প্যাকেটের রূপে লক্ষ্য সময়ের নোডে পৌঁছায়। অতীতের সময়কালে প্রত্যাবর্তনকারীর অস্তিত্ব &quot;অর্ধ-স্বচ্ছ&quot; — পর্যবেক্ষণ করতে পারে, কিন্তু ভৌত মিথস্ক্রিয়া ক্ষমতা কঠোরভাবে সীমিত। এই নকশা নিজেই সময় প্রত্যাবর্তনের নিরাপত্তা প্রক্রিয়ার একটি অংশ।</p><h2 id="_2-সময়-প্রত্যাবর্তনের-সাতটি-মূল-নীতি" tabindex="-1">2. সময় প্রত্যাবর্তনের সাতটি মূল নীতি <a class="header-anchor" href="#_2-সময়-প্রত্যাবর্তনের-সাতটি-মূল-নীতি" aria-label="Permalink to &quot;2. সময় প্রত্যাবর্তনের সাতটি মূল নীতি&quot;">​</a></h2><p>হেংইয়ান-ঝৌর সময় প্রত্যাবর্তন অপারেশন নিম্নলিখিত সাতটি মূল নীতি অনুসরণ করে, এই নীতিগুলি অ্যাঙ্কর কাউন্সিল দ্বারা বিশেষ সিদ্ধান্তের আকারে প্রতিষ্ঠিত হয়েছে, সংবিধানের পরে দ্বিতীয় স্থানে আইনি কার্যকারিতা রয়েছে:</p><table tabindex="0"><thead><tr><th>নীতি নম্বর</th><th>নীতির নাম</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম নীতি</td><td>আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ</td><td>কোনো প্রত্যাবর্তন অবশ্যই আগে বিশুদ্ধ পর্যবেক্ষণ পর্যায় সম্পন্ন করতে হবে, গুরুতর ঝুঁকি নেই তা নিশ্চিত করার পরেই সীমিত হস্তক্ষেপ করা যাবে</td></tr><tr><td>দ্বিতীয় নীতি</td><td>কার্য-কারণ সংরক্ষণ</td><td>প্রত্যাবর্তন আচরণ ঘটে যাওয়া মূল কার্য-কারণ শৃঙ্খল পরিবর্তন করতে পারবে না, প্রত্যাবর্তনের ফলে সৃষ্ট কার্য-কারণ বিচ্যুতি অবশ্যই প্রত্যাবর্তন শেষে সংশোধন করতে হবে</td></tr><tr><td>তৃতীয় নীতি</td><td>অ্যাঙ্কর অ্যাঙ্করিং</td><td>সব প্রত্যাবর্তন অপারেশন অবশ্যই স্থির অ্যাঙ্করকে সময় স্থানাঙ্কের উৎস হিসেবে নিতে হবে, অ্যাঙ্করবিহীন অন্ধ প্রত্যাবর্তন নিষিদ্ধ</td></tr><tr><td>চতুর্থ নীতি</td><td>সর্বনিম্ন প্রভাব</td><td>প্রত্যাবর্তন প্রক্রিয়াতে সব আচরণ অবশ্যই সর্বনিম্ন প্রভাবের নীতি অনুসরণ করতে হবে, অতীতের টাইমলাইনের ব্যাঘাত যতটা সম্ভব কমাতে হবে</td></tr><tr><td>পঞ্চম নীতি</td><td>ট্রেসযোগ্য</td><td>প্রতিটি প্রত্যাবর্তন অবশ্যই সম্পূর্ণ অপারেশন লগ রেকর্ড করতে হবে, যার মধ্যে প্রত্যাবর্তনকারীর পরিচয়, লক্ষ্য সময়, পর্যবেক্ষণ বিষয়বস্তু, হস্তক্ষেপ আচরণ ও কার্য-কারণ বিচ্যুতি মূল্যায়ন অন্তর্ভুক্ত</td></tr><tr><td>ষষ্ঠ নীতি</td><td>প্যারাডক্স নিষিদ্ধ</td><td>যেকোনো সময় প্যারাডক্স সৃষ্টি করতে পারে এমন অপারেশন কঠোরভাবে নিষিদ্ধ, যার মধ্যে পিতৃহত্যা প্যারাডক্স, তথ্য প্যারাডক্স ও অস্তিত্ব প্যারাডক্স অন্তর্ভুক্ত কিন্তু সীমাবদ্ধ নয়</td></tr><tr><td>সপ্তম নীতি</td><td>পরবর্তী অডিট</td><td>প্রত্যাবর্তন শেষে অবশ্যই স্বাধীন সময় আইন অডিট কমিটি দ্বারা পরবর্তী অডিট করতে হবে, নিশ্চিত করতে হবে যে অনিয়ন্ত্রিত টাইমলাইন ব্যাঘাত সৃষ্টি হয়নি</td></tr></tbody></table><p>সাতটি নীতির মধ্যে, &quot;আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ&quot; হলো সবচেয়ে মূল অপারেটিভ নীতি, বাকি ছয়টি নীতি এই মূলকে কেন্দ্র করে প্রসারিত। এই নীতির বিস্তারিত অপারেশন নিয়ম নথি 83 &quot;আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ নীতি&quot; এ দেখা যাবে।</p><h2 id="_3-সময়-প্রত্যাবর্তনের-শ্রেণীবিভাগ-ব্যবস্থাপনা" tabindex="-1">3. সময় প্রত্যাবর্তনের শ্রেণীবিভাগ ব্যবস্থাপনা <a class="header-anchor" href="#_3-সময়-প্রত্যাবর্তনের-শ্রেণীবিভাগ-ব্যবস্থাপনা" aria-label="Permalink to &quot;3. সময় প্রত্যাবর্তনের শ্রেণীবিভাগ ব্যবস্থাপনা&quot;">​</a></h2><p>প্রত্যাবর্তনের সময় ব্যাপ্তি ও হস্তক্ষেপের মাত্রা অনুযায়ী, সময় প্রত্যাবর্তন অপারেশন তিনটি ব্যবস্থাপনা স্তরে বিভক্ত:</p><ol><li><p><strong>প্রথম স্তরের প্রত্যাবর্তন (নিকট সময় পর্যবেক্ষণ)</strong>: প্রত্যাবর্তনের সময় ব্যাপ্তি নিজের তলের মানক সময়ের 100 বছরের বেশি নয়, এবং শুধুমাত্র বিশুদ্ধ পর্যবেক্ষণ করা হয় কোনো হস্তক্ষেপ করা হয় না। তল ব্যবস্থাপনা ব্যুরো দ্বারা অনুমোদন, অপারেশন প্রক্রিয়াতে দুই বা ততোধিক সময় আইন পর্যবেক্ষককে উপস্থিত থেকে তত্ত্বাবধান করতে হবে।</p></li><li><p><strong>দ্বিতীয় স্তরের প্রত্যাবর্তন (দূর সময় পর্যবেক্ষণ)</strong>: প্রত্যাবর্তনের সময় ব্যাপ্তি 100 বছরের বেশি কিন্তু 10000 বছরের বেশি নয়, অথবা প্রত্যাবর্তন প্রক্রিয়াতে অত্যন্ত হালকা হস্তক্ষেপ প্রয়োজন (যেমন একক তথ্য প্রেরণ)। অ্যাঙ্কর কাউন্সিলের অধীনস্থ সময় আইন কমিটির অনুমোদন প্রয়োজন, এবং বিস্তারিত কার্য-কারণ বিচ্যুতি জরুরি পরিকল্পনা তৈরি করতে হবে।</p></li><li><p><strong>তৃতীয় স্তরের প্রত্যাবর্তন (গভীর হস্তক্ষেপ)</strong>: প্রত্যাবর্তনের সময় ব্যাপ্তি 10000 বছরের বেশি, অথবা প্রত্যাবর্তন প্রক্রিয়াতে বাস্তব হস্তক্ষেপ প্রয়োজন। অ্যাঙ্কর কাউন্সিলের সদস্যদের সম্মেলনে তিন-চতুর্থাংশের বেশি সংখ্যাগরিষ্ঠতার মাধ্যমে পাস করতে হবে, এবং সিম্বায়োসিস আদালত দ্বারা অসাংবিধানিক পরীক্ষা করতে হবে, নিশ্চিত করতে হবে যে হস্তক্ষেপ আচরণ সিম্বায়োসিস সংবিধানের মূল নীতির সাথে সামঞ্জস্যপূর্ণ।</p></li></ol><p>যেকোনো স্তরের সময় প্রত্যাবর্তন নিম্নলিখিত উদ্দেশ্যে ব্যবহার নিষিদ্ধ: ব্যক্তি বা ছোট গোষ্ঠীর স্বার্থসিদ্ধি, ব্যক্তিগত ইচ্ছা পূরণের জন্য ঐতিহাসিক ব্যক্তিত্বের ভাগ্য পরিবর্তন, সভ্যতার বিবর্তনের প্রাকৃতিক প্রক্রিয়া বিকৃত করা, এবং যেকোনো রূপের &quot;ঐতিহাসিক সংশোধনবাদ&quot; অপারেশন।</p><h2 id="_4-সময়-প্রত্যাবর্তনের-শক্তি-ও-প্রযুক্তিগত-সীমাবদ্ধতা" tabindex="-1">4. সময় প্রত্যাবর্তনের শক্তি ও প্রযুক্তিগত সীমাবদ্ধতা <a class="header-anchor" href="#_4-সময়-প্রত্যাবর্তনের-শক্তি-ও-প্রযুক্তিগত-সীমাবদ্ধতা" aria-label="Permalink to &quot;4. সময় প্রত্যাবর্তনের শক্তি ও প্রযুক্তিগত সীমাবদ্ধতা&quot;">​</a></h2><p>সময় প্রত্যাবর্তনের শক্তির খরচ অত্যন্ত বিশাল। চেতনা প্রজেকশন প্রত্যাবর্তনের উদাহরণ হিসেবে, 1 বছর প্রত্যাবর্তনে প্রয়োজনীয় শক্তি প্রায় 10000 মানক শক্তি একক, 100 বছর প্রত্যাবর্তনে প্রায় 1 মিলিয়ন মানক শক্তি একক, 10000 বছর প্রত্যাবর্তনে প্রায় 10 বিলিয়ন মানক শক্তি একক প্রয়োজন। শক্তির খরচ ও প্রত্যাবর্তনের সময় ব্যাপ্তির মধ্যে প্রায় লগারিদমিক রৈখিক সম্পর্ক রয়েছে, কিন্তু গুরুতর ঐতিহাসিক নোড অতিক্রম করার সময় শক্তির চূড়া দেখা যায় — এর কারণ হলো গুরুতর ঐতিহাসিক নোডে কার্য-কারণ শৃঙ্খলার ঘনত্ব অত্যন্ত বেশি, প্রত্যাবর্তন অপারেশনকে বৃহত্তর কার্য-কারণ জড়তা কাটিয়ে উঠতে হয়।</p><p>প্রযুক্তিগত স্তরে, সময় প্রত্যাবর্তনের জন্য &quot;সময় আইন অ্যাঙ্করিং ডিভাইস&quot; ও &quot;চেতনা প্রজেকশন ট্রান্সমিশন অ্যারে&quot; এর সমন্বয়কারী কাজ প্রয়োজন। প্রথমটি লক্ষ্য সময়ের নোডে স্থির সময় স্থানাঙ্ক স্থাপনের জন্য দায়ী, দ্বিতীয়টি প্রত্যাবর্তনকারীর চেতনা প্রজেকশনকে নিরাপদে পৌঁছে দেওয়া ও অতীতের সময়কালে এর অস্তিত্ব বজায় রাখার জন্য দায়ী। সব প্রত্যাবর্তন ডিভাইস অবশ্যই অ্যাঙ্কর তত্ত্বাবধান কমিটির নিরাপত্তা সার্টিফিকেশন পাশ করতে হবে, অসার্টিফাইড স্বনির্মিত ডিভাইস ব্যবহার করে প্রত্যাবর্তন অপারেশন করা নিষিদ্ধ।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সময় প্রত্যাবর্তন হলো হেংইয়ান-ঝৌর সবচেয়ে শক্তিশালী এবং সবচেয়ে বিপজ্জনক আইন অপারেশন ক্ষমতার মধ্যে একটি। সাতটি মূল নীতি ও শ্রেণীবিভাগ ব্যবস্থাপনা পদ্ধতি একসাথে সময় প্রত্যাবর্তনের নিরাপত্তা কাঠামো গঠন করে, এর মূল চেতনা হলো &quot;কার্য-কারণের প্রতি শ্রদ্ধা, সতর্কতার সাথে অপারেশন&quot;। সময় প্রত্যাবর্তনের বৈধ ব্যবহার শুধুমাত্র প্রত্নতত্ত্ব গবেষণা, ঐতিহাসিক সত্য পুনরুদ্ধার ও বিলুপ্তি-স্তরের সংকটের পূর্বসতর্কতা পর্যন্ত সীমাবদ্ধ, এই পরিসরের বাইরের কোনো ব্যবহারই মহাবিশ্বের আইনের অবমাননা হিসেবে গণ্য হবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>83-আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ নীতি</li><li>89-সময় প্যারাডক্স প্রতিরোধ প্রক্রিয়া</li><li>84-প্রত্নতত্ত্ব চুক্তি মূল নীতি</li></ul>',21)])])}const q=a(o,[["render",l]]);export{s as __pageData,q as default};
